import * as fs from 'fs';

const logPath = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_eevp9_yl/app.log';
const content = fs.readFileSync(logPath, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

const levelCounts: Map<string, number> = new Map();
const componentErrorCounts: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
const hourCounts: Map<string, number> = new Map();

const regex = /^\[(\d{4}-\d{2}-\d{2}) (\d{2}):(\d{2}):(\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
    const match = line.match(regex);
    if (!match) continue;

    const hour = match[2];
    const level = match[5];
    const component = match[6];
    const message = match[7];

    levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

    if (level === 'ERROR') {
        componentErrorCounts.set(component, (componentErrorCounts.get(component) || 0) + 1);
        errorMessages.add(message);
    }

    hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);
}

const out: string[] = [];
out.push('=== Log Analysis ===');
out.push('');
out.push('Entries by Level:');

const sortedLevels = Array.from(levelCounts.keys()).sort();
for (const level of sortedLevels) {
    out.push(`  ${level}: ${levelCounts.get(level)}`);
}

out.push('');

let maxComponent = '';
let maxCount = -1;
const sortedComponents = Array.from(componentErrorCounts.keys()).sort();
for (const comp of sortedComponents) {
    const count = componentErrorCounts.get(comp)!;
    if (count > maxCount) {
        maxCount = count;
        maxComponent = comp;
    }
}
out.push(`Component with Most Errors: ${maxComponent} (${maxCount} errors)`);
out.push('');

out.push('Unique Error Messages:');
const sortedMessages = Array.from(errorMessages).sort();
for (const msg of sortedMessages) {
    out.push(`  - ${msg}`);
}

out.push('');

let busiestHour = '';
let busiestCount = -1;
const sortedHours = Array.from(hourCounts.keys()).sort();
for (const h of sortedHours) {
    const count = hourCounts.get(h)!;
    if (count > busiestCount) {
        busiestCount = count;
        busiestHour = h;
    }
}
out.push(`Busiest Hour: ${busiestHour}:00 (${busiestCount} entries)`);

process.stdout.write(out.join('\n') + '\n');

