import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_eevp9_yl/employees.csv";

        List<String> lines = new ArrayList<>();
        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line;
        while ((line = br.readLine()) != null) {
            lines.add(line);
        }
        br.close();

        List<String[]> records = new ArrayList<>();
        for (int i = 1; i < lines.size(); i++) {
            String l = lines.get(i).trim();
            if (l.isEmpty()) continue;
            String[] parts = l.split(",");
            if (parts.length >= 6) {
                records.add(parts);
            }
        }

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCounts = new TreeMap<>();
        double totalBudget = 0;
        String highestName = "";
        double highestSalary = Double.NEGATIVE_INFINITY;

        for (String[] r : records) {
            String name = r[1].trim();
            String dept = r[2].trim();
            double salary = Double.parseDouble(r[3].trim());

            deptSalaries.computeIfAbsent(dept, k -> new ArrayList<>()).add(salary);
            deptCounts.put(dept, deptCounts.getOrDefault(dept, 0) + 1);
            totalBudget += salary;

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }
        }

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            double avg = entry.getValue().stream().mapToDouble(Double::doubleValue).average().orElse(0);
            System.out.printf("  %s: $%,.2f%n", entry.getKey(), avg);
        }
        System.out.println();
        System.out.printf("Highest Paid: %s ($%,.0f)%n", highestName, highestSalary);
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, Integer> entry : deptCounts.entrySet()) {
            if (entry.getValue() > 2) {
                System.out.printf("  %s (%d employees)%n", entry.getKey(), entry.getValue());
            }
        }
        System.out.println();
        System.out.printf("Total Budget: $%,.0f%n", totalBudget);
    }
}

