import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_eevp9_yl/app.log";

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorComponentCounts = new TreeMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new TreeMap<>();

        Pattern pattern = Pattern.compile("\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.+)");

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;

                Matcher m = pattern.matcher(line);
                if (m.matches()) {
                    String hour = m.group(2);
                    String level = m.group(3);
                    String component = m.group(4);
                    String message = m.group(5);

                    levelCounts.merge(level, 1, Integer::sum);
                    hourCounts.merge(hour, 1, Integer::sum);

                    if (level.equals("ERROR")) {
                        errorComponentCounts.merge(component, 1, Integer::sum);
                        errorMessages.add(message);
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n");
        sb.append("\n");
        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> e : levelCounts.entrySet()) {
            sb.append("  ").append(e.getKey()).append(": ").append(e.getValue()).append("\n");
        }
        sb.append("\n");
        sb.append("Component with Most Errors: ");
        String topComponent = "";
        int topCount = -1;
        for (Map.Entry<String, Integer> e : errorComponentCounts.entrySet()) {
            if (e.getValue() > topCount) {
                topCount = e.getValue();
                topComponent = e.getKey();
            }
        }
        sb.append(topComponent).append(" (").append(topCount).append(" errors)\n");
        sb.append("\n");
        sb.append("Unique Error Messages:\n");
        for (String msg : errorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");
        sb.append("Busiest Hour: ");
        String topHour = "";
        int topHourCount = -1;
        for (Map.Entry<String, Integer> e : hourCounts.entrySet()) {
            if (e.getValue() > topHourCount) {
                topHourCount = e.getValue();
                topHour = e.getKey();
            }
        }
        sb.append(topHour).append(":00 (").append(topHourCount).append(" entries)\n");

        System.out.print(sb.toString());
    }
}

