import * as fs from 'fs';

function isPlainObject(val: unknown): val is Record<string, unknown> {
  return val !== null && typeof val === 'object' && !Array.isArray(val);
}

function deepMerge(a: unknown, b: unknown): unknown {
  if (isPlainObject(a) && isPlainObject(b)) {
    const result: Record<string, unknown> = {};
    const keys = new Set<string>([...Object.keys(a), ...Object.keys(b)]);
    for (const key of keys) {
      if (key in a && key in b) {
        result[key] = deepMerge(a[key], b[key]);
      } else if (key in a) {
        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }
    return result;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    const result: unknown[] = [...a];
    const seen: Set<string> = new Set(a.map((item) => JSON.stringify(item)));
    for (const item of b) {
      const key = JSON.stringify(item);
      if (!seen.has(key)) {
        seen.add(key);
        result.push(item);
      }
    }
    return result;
  }
  return b;
}

function sortedStringify(val: unknown, indent: number): string {
  const pad: string = '  '.repeat(indent);
  const innerPad: string = '  '.repeat(indent + 1);

  if (val === null) return 'null';
  if (val === undefined) return 'null';
  if (typeof val === 'string') return JSON.stringify(val);
  if (typeof val === 'number' || typeof val === 'boolean') return String(val);

  if (Array.isArray(val)) {
    if (val.length === 0) return '[]';
    const items: string[] = val.map((item) => innerPad + sortedStringify(item, indent + 1));
    return '[\n' + items.join(',\n') + '\n' + pad + ']';
  }

  if (typeof val === 'object') {
    const obj = val as Record<string, unknown>;
    const keys: string[] = Object.keys(obj).sort();
    if (keys.length === 0) return '{}';
    const items: string[] = keys.map(
      (key) => innerPad + JSON.stringify(key) + ': ' + sortedStringify(obj[key], indent + 1)
    );
    return '{\n' + items.join(',\n') + '\n' + pad + '}';
  }

  return String(val);
}

