import * as fs from 'fs';

const csvPath = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_eevp9_yl/employees.csv';
const raw = fs.readFileSync(csvPath, 'utf-8').replace(/^\uFEFF/, '');
const lines = raw.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim().split('\n');

interface Employee {
  employee_id: string;
  name: string;
  department: string;
  salary: number;
  start_date: string;
  rating: string;
}

const employees: Employee[] = [];
for (let i = 1; i < lines.length; i++) {
  const parts = lines[i].split(',').map(p => p.trim());
  if (parts.length < 6) continue;
  employees.push({
    employee_id: parts[0],
    name: parts[1],
    department: parts[2],
    salary: parseFloat(parts[3]),
    start_date: parts[4],
    rating: parts[5]
  });
}

const deptSalaries: Map<string, number[]> = new Map();
