use std::collections::BTreeMap;
use std::fs;

fn format_commas(n: u64) -> String {
    let s = n.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_commas_decimal(n: f64) -> String {
    let rounded = (n * 100.0).round();
    let int_part = (rounded / 100.0) as u64;
    let dec_part = (rounded % 100.0) as u32;
    let int_str = format_commas(int_part);
    format!("{},{}", int_str, format!("{:02}", dec_part))
}

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_eevp9_yl/employees.csv";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let lines: Vec<&str> = content.lines().collect();
    if lines.is_empty() {
        return;
    }

    let mut dept_salaries: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary: f64 = 0.0;
    let mut total_budget: f64 = 0.0;

    for line in &lines[1..] {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let fields: Vec<&str> = trimmed.split(',').collect();
        let name = fields[1].trim().to_string();
        let department = fields[2].trim().to_string();
        let salary: f64 = fields[3].trim().parse().expect("Failed to parse salary");

        dept_salaries.entry(department).or_insert_with(Vec::new).push(salary);

        if salary > highest_paid_salary {
            highest_paid_salary = salary;
            highest_paid_name = name;
        }

        total_budget += salary;
    }

    print!("=== Salary Report ===\n");
    print!("\n");
    print!("Average Salary by Department:\n");
    for (dept, salaries) in &dept_salaries {
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        print!("  {}: ${}\n", dept, format_commas_decimal(avg));
    }
    print!("\n");
    print!("Highest Paid: {} (${})\n", highest_paid_name, format_commas(highest_paid_salary as u64));
    print!("\n");
    print!("Departments with >2 employees:\n");
    for (dept, salaries) in &dept_salaries {
        if salaries.len() > 2 {
            print!("  {} ({} employees)\n", dept, salaries.len());
        }
    }
    print!("\n");
    print!("Total Budget: ${}\n", format_commas(total_budget as u64));
}

