    let fullRange = NSMakeRange(0, nsLine.length)
    guard let match = regex.firstMatch(in: line, range: fullRange), match.numberOfRanges == 6 else {
        continue
    }

    let hourStr = nsLine.substring(with: match.range(at: 2))
    let level = nsLine.substring(with: match.range(at: 3))
    let component = nsLine.substring(with: match.range(at: 4))
    let message = nsLine.substring(with: match.range(at: 5))

    let hour = Int(hourStr) ?? 0
    hourCounts[hour, default: 0] += 1

    levelCounts[level, default: 0] += 1

    if level == "ERROR" {
        componentErrorCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

