public class Main {
    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString();

        List<String[]> products = new ArrayList<>();

        Pattern objPattern = Pattern.compile("\\{[^{}]*\\}");
        Matcher objMatcher = objPattern.matcher(json);

        Pattern namePattern = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]*)\"");
        Pattern pricePattern = Pattern.compile("\"price\"\\s*:\\s*(-?[\\d.]+)");

        while (objMatcher.find()) {
            String obj = objMatcher.group();
            Matcher nm = namePattern.matcher(obj);
            Matcher pm = pricePattern.matcher(obj);
            if (nm.find() && pm.find()) {
                String name = nm.group(1);
                double price = Double.parseDouble(pm.group(1));
                products.add(new String[]{name, String.valueOf(price)});
            }
        }

        List<String[]> filtered = new ArrayList<>();
        for (String[] p : products) {
            if (Double.parseDouble(p[1]) > 50.00) {
                filtered.add(p);
            }
        }

        filtered.sort((a, b) -> a[0].compareTo(b[0]));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();

        double total = 0;
        for (String[] p : filtered) {
            double price = Double.parseDouble(p[1]);
            total += price;
            System.out.printf("%s: $%.2f\n", p[0], price);
        }

        System.out.println();
        System.out.println("Count: " + filtered.size());
        System.out.printf("Total: $%.2f\n", total);
    }
}

