use std::fs;

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_eevp9_yl/app.log";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut error_components: HashMap<String, usize> = HashMap::new();
    let mut error_messages: Vec<String> = Vec::new();
    let mut hour_counts: HashMap<u32, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || !line.starts_with('[') {
            continue;
        }
        let bracket_end = line.find(']').unwrap();
        let timestamp = &line[1..bracket_end];
        let hour: u32 = timestamp[11..13].parse().unwrap();
        *hour_counts.entry(hour).or_insert(0) += 1;

        let after_bracket = &line[bracket_end + 1..];
        let after_space = after_bracket.trim_start();

        let paren_start = after_space.find('(').unwrap();
        let level = after_space[..paren_start].trim_end().to_string();
        *level_counts.entry(level.clone()).or_insert(0) += 1;

        let paren_end = after_space.find(')').unwrap();
        let component = after_space[paren_start + 1..paren_end].to_string();

        let after_paren = &after_space[paren_end + 1..];
        let message = after_paren.trim().trim_start_matches('-').trim().to_string();

        if level == "ERROR" {
            *error_components.entry(component).or_insert(0) += 1;
            error_messages.push(message);
        }
    }

    println!("=== Log Analysis ===");
    println!();

    println!("Entries by Level:");
    let mut levels: Vec<&String> = level_counts.keys().collect();
    levels.sort();
    for level in levels {
        println!("  {}: {}", level, level_counts[level]);
    }
    println!();

    let mut max_errors = 0usize;
    let mut max_component = String::new();
    let mut sorted_comps: Vec<&String> = error_components.keys().collect();
    sorted_comps.sort();
    for comp in sorted_comps {
        let count = error_components[comp];
        if count > max_errors {
            max_errors = count;
            max_component = comp.clone();
        }
    }
    println!("Component with Most Errors: {} ({} errors)", max_component, max_errors);
    println!();

    println!("Unique Error Messages:");
    let mut unique_msgs: Vec<String> = error_messages;
    unique_msgs.sort();
    unique_msgs.dedup();
    for msg in &unique_msgs {
        println!("  - {}", msg);
    }
    println!();

    let mut max_hour_entries = 0usize;
    let mut busiest_hour = 0u32;
    let mut sorted_hours: Vec<u32> = hour_counts.keys().copied().collect();
    sorted_hours.sort();
    for h in sorted_hours {
        let count = hour_counts[&h];
        if count > max_hour_entries {
            max_hour_entries = count;
            busiest_hour = h;
        }
    }
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, max_hour_entries);
}

