let content = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

func formatInt(_ n: Int) -> String {
    let s = String(abs(n))
    var result = ""
    var count = 0
    for c in s.reversed() {
        if count > 0 && count % 3 == 0 {
            result = "," + result
        }
        result = String(c) + result
        count += 1
    }
    return (n < 0 ? "-" : "") + result
}

func formatDecimal(_ n: Double) -> String {
    let s = String(format: "%.2f", n)
    let parts = s.components(separatedBy: ".")
    return formatInt(Int(parts[0])!) + "." + parts[1]
}

var employees: [(name: String, department: String, salary: Double)] = []

for line in lines.dropFirst() {
    let parts = line.components(separatedBy: ",")
    guard parts.count >= 6 else { continue }
    let name = parts[1].trimmingCharacters(in: .whitespaces)
    let department = parts[2].trimmingCharacters(in: .whitespaces)
    let salaryStr = parts[3].trimmingCharacters(in: .whitespaces)
    let salary = Double(salaryStr) ?? 0
    employees.append((name, department, salary))
}

var deptSalaries: [String: [Double]] = [:]
for emp in employees {
    deptSalaries[emp.department, default: []].append(emp.salary)
}

let highestPaid = employees.max { $0.salary < $1.salary }!

var deptCounts: [String: Int] = [:]
for emp in employees {
    deptCounts[emp.department, default: 0] += 1
}

let totalBudget = employees.reduce(0.0) { $0 + $1.salary }

