        if (obj instanceof Boolean) return obj.toString();
        if (obj instanceof Long) return obj.toString();
        if (obj instanceof Double) {
            double d = (Double) obj;
            if (d == Math.floor(d) && !Double.isInfinite(d) && Math.abs(d) < 1e15) {
                return String.valueOf((long) d) + ".0";
