            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) sb.append(",");
                sb.append(canonicalJson(list.get(i)));
            }
            sb.append("]");
            return sb.toString();
        }
        return obj.toString();
