    static void printJson(Object obj, int indent, StringBuilder sb) {
        if (obj == null) {
            sb.append("null");
        } else if (obj instanceof String) {
            sb.append("\"").append(escapeString((String) obj)).append("\"");
        } else if (obj instanceof Boolean) {
            sb.append(obj.toString());
        } else if (obj instanceof Long) {
            sb.append(obj.toString());
        } else if (obj instanceof Double) {
            double d = (Double) obj;
            if (d == Math.floor(d) && !Double.isInfinite(d) && Math.abs(d) < 1e15) {
                sb.append((long) d).append(".0");
            } else {
                sb.append(obj.toString());
            }
        } else if (obj instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) obj;
            if (map.isEmpty()) { sb.append("{}"); return; }
            List<String> keys = new ArrayList<>(map.keySet());
            Collections.sort(keys);
            sb.append("{\n");
            String pad = "  ".repeat(indent + 1);
            String padEnd = "  ".repeat(indent);
            for (int i = 0; i < keys.size(); i++) {
                sb.append(pad);
                sb.append("\"").append(escapeString(keys.get(i))).append("\": ");
                printJson(map.get(keys.get(i)), indent + 1, sb);
                if (i < keys.size() - 1) sb.append(",");
                sb.append("\n");
            }
            sb.append(padEnd).append("}");
        } else if (obj instanceof List) {
            List<Object> list = (List<Object>) obj;
            if (list.isEmpty()) { sb.append("[]"); return; }
            sb.append("[\n");
            String pad = "  ".repeat(indent + 1);
            String padEnd = "  ".repeat(indent);
            for (int i = 0; i < list.size(); i++) {
                sb.append(pad);
                printJson(list.get(i), indent + 1, sb);
                if (i < list.size() - 1) sb.append(",");
                sb.append("\n");
            }
            sb.append(padEnd).append("]");
        }
    }

    static String escapeString(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

