    for (int i = 0; i < len; i++) {
        if (tmp[i] == '.') { dotpos = i; break; }
    }

    int intlen = (dotpos == -1) ? len : dotpos;

    int pos = 0;
    for (int i = 0; i < intlen; i++) {
        if (i > 0 && (intlen - i) % 3 == 0) {
            buf[pos++] = ',';
        }
        buf[pos++] = tmp[i];
    }
    if (dotpos != -1) {
        buf[pos++] = '.';
        for (int i = dotpos + 1; i < len; i++) {
            buf[pos++] = tmp[i];
        }
    }
