#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *run_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;

    size_t cap = 4096;
    char *buf = malloc(cap);
    if (!buf) { pclose(fp); return NULL; }

    size_t len = 0;
    int c;
    while ((c = fgetc(fp)) != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) { free(buf); pclose(fp); return NULL; }
            buf = tmp;
        }
        buf[len++] = (char)c;
    }
    pclose(fp);
    buf[len] = '\0';

    while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r' ||
                       buf[len - 1] == ' '  || buf[len - 1] == '\t')) {
        buf[--len] = '\0';
    }

    return buf;
}

int main(void) {
    char *hostname   = run_command("hostname");
    char *os         = run_command("uname -s");
    char *arch       = run_command("uname -m");
    char *username   = run_command("whoami");

    if (!hostname || !os || !arch || !username) {
        free(hostname); free(os); free(arch); free(username);
        return 1;
    }

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", arch);
    printf("  \"username\": \"%s\"\n", username);
    printf("}\n");

    free(hostname);
    free(os);
    free(arch);
    free(username);

    return 0;
}

