use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

struct Parser<'a> {
    s: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { s: s.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.s.len()
            && (self.s[self.pos] == b' '
                || self.s[self.pos] == b'\t'
                || self.s[self.pos] == b'\n'
                || self.s[self.pos] == b'\r')
        {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<u8> {
        self.s.get(self.pos).copied()
    }

    fn expect(&mut self, c: u8) {
        self.skip_ws();
        assert_eq!(
            self.peek(),
            Some(c),
            "Expected '{}' at pos {}",
            c as char,
            self.pos
        );
        self.pos += 1;
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Json::Str(self.parse_string()),
            Some(b't') => {
                self.pos += 4;
                Json::Bool(true)
            }
            Some(b'f') => {
                self.pos += 5;
                Json::Bool(false)
            }
            Some(b'n') => {
                self.pos += 4;
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut result = String::new();
        loop {
            let c = self.s[self.pos];
            self.pos += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let esc = self.s[self.pos];
                    self.pos += 1;
                    match esc {
                        b'"' => result.push('"'),
                        b'\\' => result.push('\\'),
                        b'/' => result.push('/'),
                        b'n' => result.push('\n'),
                        b't' => result.push('\t'),
                        b'r' => result.push('\r'),
                        b'b' => result.push('\u{0008}'),
                        b'f' => result.push('\u{000C}'),
                        b'u' => {
                            let hex =
                                std::str::from_utf8(&self.s[self.pos..self.pos + 4]).unwrap();
                            let code = u32::from_str_radix(hex, 16).unwrap();
                            self.pos += 4;
                            result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => {}
                    }
                }
                _ => result.push(c as char),
            }
        }
        result
    }

    fn parse_number(&mut self) -> Json {
        self.skip_ws();
        let start = self.pos;
        if self.peek() == Some(b'-') {
            self.pos += 1;
        }
        while self.pos < self.s.len()
            && (self.s[self.pos].is_ascii_digit()
                || self.s[self.pos] == b'.'
                || self.s[self.pos] == b'e'
                || self.s[self.pos] == b'E'
                || self.s[self.pos] == b'+'
                || self.s[self.pos] == b'-')
        {
            self.pos += 1;
        }
        let num_str = std::str::from_utf8(&self.s[start..self.pos]).unwrap();
        Json::Num(num_str.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> Json {
        self.expect(b'[');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b']') => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("Expected ',' or ']' in array at pos {}", self.pos),
            }
        }
        Json::Arr(items)
    }

    fn parse_object(&mut self) -> Json {
        self.expect(b'{');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Json::Obj(items);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.expect(b':');
            let val = self.parse_value();
            items.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b'}') => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("Expected ',' or '}}' in object at pos {}", self.pos),
            }
        }
        Json::Obj(items)
    }
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");

    let request =
        "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream
        .write_all(request.as_bytes())
        .expect("Failed to write request");

    let mut buf = Vec::new();
    stream
        .read_to_end(&mut buf)
        .expect("Failed to read response");

    let response = String::from_utf8_lossy(&buf).to_string();

    let body_start = response.find("\r\n\r\n").expect("No HTTP body found") + 4;
    let body = &response[body_start..];

    let mut parser = Parser::new(body);
    let json = parser.parse_value();

    let mut products: Vec<(String, f64)> = Vec::new();

    if let Json::Arr(arr) = json {
        for item in arr {
            if let Json::Obj(fields) = item {
                let mut name = String::new();
                let mut price = 0.0f64;
                for (k, v) in &fields {
                    if k == "name" {
                        if let Json::Str(s) = v {
                            name = s.clone();
                        }
                    } else if k == "price" {
                        if let Json::Num(n) = v {
                            price = *n;
                        }
                    }
                }
                products.push((name, price));
            }
        }
    }

    products.retain(|(_, p)| *p > 50.00);
    products.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &products {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", products.len());
    let total: f64 = products.iter().map(|(_, p)| p).sum();
    println!("Total: ${:.2}", total);
}

