import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path root = Paths.get("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_eevp9_yl/project_tree");

        Map<String, List<String[]>> extMap = new TreeMap<>();

        Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                if (Files.isSymbolicLink(file)) {
                    return FileVisitResult.CONTINUE;
                }

                Path relPath = root.relativize(file);
                String relPathStr = relPath.toString().replace('\\', '/');

                long charCount = Files.size(file);
                int lineCount = countLines(file);

                String fileName = file.getFileName().toString();
                String ext = getExtension(fileName);

                extMap.computeIfAbsent(ext, k -> new ArrayList<>())
                      .add(new String[]{relPathStr, String.valueOf(lineCount), String.valueOf(charCount)});

                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
                if (Files.isSymbolicLink(dir)) {
                    return FileVisitResult.SKIP_SUBTREE;
                }
                return FileVisitResult.CONTINUE;
            }
        });

        for (List<String[]> files : extMap.values()) {
            files.sort(Comparator.comparing(a -> a[0]));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        int totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<String[]>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<String[]> files = entry.getValue();

            long extLines = 0;
            long extChars = 0;
            for (String[] f : files) {
                extLines += Long.parseLong(f[1]);
                extChars += Long.parseLong(f[2]);
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(files.size()).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (String[] f : files) {
                sb.append("    ").append(f[0]).append(": ").append(f[1]).append(" lines, ").append(f[2]).append(" chars\n");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    private static String getExtension(String fileName) {
        int lastDot = fileName.lastIndexOf('.');
        if (lastDot <= 0) {
            return "";
        }
        return fileName.substring(lastDot);
    }

    private static int countLines(Path file) throws IOException {
        try (BufferedReader reader = Files.newBufferedReader(file)) {
            int lines = 0;
            int c;
            boolean inLine = false;
            while ((c = reader.read()) != -1) {
                if (c == '\n') {
                    lines++;
                    inLine = false;
                } else {
                    inLine = true;
                }
            }
            if (inLine) {
                lines++;
            }
            return lines;
        }
    }
}

