    }

    private static int countLines(Path file) throws IOException {
        try (BufferedReader reader = Files.newBufferedReader(file)) {
            int lines = 0;
            int c;
            boolean inLine = false;
            while ((c = reader.read()) != -1) {
                if (c == '\n') {
                    lines++;
                    inLine = false;
                } else {
                    inLine = true;
                }
            }
            if (inLine) {
                lines++;
            }
            return lines;
        }
    }
