const rootDir = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_eevp9_yl/project_tree';

interface FileEntry {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(buf: Buffer): number {
  if (buf.length === 0) return 0;
  let newlineCount = 0;
  for (let i = 0; i < buf.length; i++) {
    if (buf[i] === 0x0a) newlineCount++;
  }
  const lastIsNewline = buf[buf.length - 1] === 0x0a;
  return newlineCount + (lastIsNewline ? 0 : 1);
}

function walkDir(dir: string, rootDir: string, visited: Set<string>, result: Map<string, FileEntry[]>): void {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      const resolved = fs.realpathSync(fullPath);
      if (visited.has(resolved)) continue;
      visited.add(resolved);
      walkDir(fullPath, rootDir, visited, result);
    } else if (entry.isFile()) {
      const content = fs.readFileSync(fullPath);
      const chars = content.length;
      const lines = countLines(content);

      const relPath = path.relative(rootDir, fullPath).split(path.sep).join('/');
      const ext = path.extname(entry.name);

      if (!result.has(ext)) {
        result.set(ext, []);
      }
      result.get(ext)!.push({ relativePath: relPath, lines, chars });
    }
  }
}

