  const visited = new Set<string>();
  visited.add(fs.realpathSync(rootDir));

  const groups: Map<string, FileEntry[]> = new Map();
  walkDir(rootDir, rootDir, visited, groups);

  const sortedExts = Array.from(groups.keys()).sort();

  let output = '=== File Tree Analysis ===\n\n';

  let totalFiles = 0;
  let totalLines = 0;
  let totalChars = 0;

  for (const ext of sortedExts) {
    const files = groups.get(ext)!.sort((a, b) => a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0);
    const extTotalLines = files.reduce((s, f) => s + f.lines, 0);
    const extTotalChars = files.reduce((s, f) => s + f.chars, 0);

    output += `Extension: ${ext}\n`;
    output += `  Files: ${files.length}\n`;
    output += `  Total Lines: ${extTotalLines}\n`;
    output += `  Total Characters: ${extTotalChars}\n`;

    for (const f of files) {
      output += `    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars\n`;
    }

    totalFiles += files.length;
    totalLines += extTotalLines;
    totalChars += extTotalChars;
  }

  output += `\nTotal: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`;

  process.stdout.write(output);
}

