    if file.read_to_end(&mut buf).is_err() {
        return (0, 0);
    }
    let chars = buf.len();
    let lines = if buf.is_empty() {
        0
    } else {
        let newline_count = buf.iter().filter(|&&b| b == b'\n').count();
        if buf.last() == Some(&b'\n') {
            newline_count
        } else {
            newline_count + 1
        }
    };
    (lines, chars)
}

fn walk_dir(
    dir: &Path,
    base: &Path,
    results: &mut BTreeMap<String, Vec<(String, FileStats)>>,
    visited: &mut HashSet<u64>,
) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries.flatten() {
        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            let metadata = match fs::metadata(&path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            let ino = metadata.ino();
            if !visited.insert(ino) {
                continue;
            }
            walk_dir(&path, base, results, visited);
        } else if path.is_file() {
            let (lines, chars) = count_lines_and_chars(&path);
            let relative = match path.strip_prefix(base) {
                Ok(r) => r,
                Err(_) => continue,
            };
            let rel_str = relative.to_string_lossy().replace('\\', "/");

            let ext = path
                .extension()
                .map(|e| format!(".{}", e.to_string_lossy()))
                .unwrap_or_else(|| String::new());

            results
                .entry(ext)
                .or_default()
                .push((rel_str, FileStats { lines, chars }));
        }
    }
}

fn main() {
    let base = PathBuf::from(
        "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_eevp9_yl/project_tree",
    );

    let mut results: BTreeMap<String, Vec<(String, FileStats)>> = BTreeMap::new();
    let mut visited: HashSet<u64> = HashSet::new();

    if let Ok(metadata) = fs::metadata(&base) {
        visited.insert(metadata.ino());
    }

    walk_dir(&base, &base, &mut results, &mut visited);

    for files in results.values_mut() {
        files.sort_by(|a, b| a.0.cmp(&b.0));
    }

    let mut total_files = 0usize;
    let mut total_lines = 0usize;
    let mut total_chars = 0usize;

    print!("=== File Tree Analysis ===\n");
    println!();

    for (ext, files) in &results {
        let file_count = files.len();
        let ext_lines: usize = files.iter().map(|f| f.1.lines).sum();
        let ext_chars: usize = files.iter().map(|f| f.1.chars).sum();

        total_files += file_count;
        total_lines += ext_lines;
        total_chars += ext_chars;

        println!("Extension: {}", ext);
        println!("  Files: {}", file_count);
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_chars);
        for (rel, stats) in files {
            println!("    {}: {} lines, {} chars", rel, stats.lines, stats.chars);
        }
    }

    println!();
    println!(
        "Total: {} files, {} lines, {} characters",
        total_files, total_lines, total_chars
    );
}
