function multiplyMatrix(a: number[][], b: number[][]): number[][] {
    const rows = a.length;
    const cols = b[0].length;
    const inner = b.length;
    const result: number[][] = Array.from({ length: rows }, () => Array(cols).fill(0));
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            for (let k = 0; k < inner; k++) {
                result[i][j] += a[i][k] * b[k][j];
            }
        }
    }
    return result;
}

function determinant(m: number[][]): number {
    const n = m.length;
    if (n === 1) return m[0][0];
    if (n === 2) return m[0][0] * m[1][1] - m[0][1] * m[1][0];
    let det = 0;
    for (let j = 0; j < n; j++) {
        const minor: number[][] = [];
        for (let i = 1; i < n; i++) {
            minor.push(m[i].filter((_, k) => k !== j));
        }
        det += (j % 2 === 0 ? 1 : -1) * m[0][j] * determinant(minor);
    }
    return det;
}

function formatMatrix(m: number[][]): string {
    return m.map(row => "  " + row.map(v => String(v).padStart(4)).join(" ")).join("\n");
}

