static void print_string_escaped(const char *s, FILE *f) {
    fputc('"', f);
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        switch (*p) {
            case '"': fputs("\\\"", f); break;
            case '\\': fputs("\\\\", f); break;
            case '\b': fputs("\\b", f); break;
            case '\f': fputs("\\f", f); break;
            case '\n': fputs("\\n", f); break;
            case '\r': fputs("\\r", f); break;
            case '\t': fputs("\\t", f); break;
            default:
                if (*p < 0x20) fprintf(f, "\\u%04x", *p);
                else fputc(*p, f);
                break;
        }
    }
    fputc('"', f);
}

static void print_number(double d, FILE *f) {
    if (isinf(d) || isnan(d)) { fputs("null", f); return; }
    if (d == (double)(long long)d && fabs(d) < 1e15) {
        fprintf(f, "%lld", (long long)d);
    } else {
        /* Use %g but ensure it looks like a valid JSON number */
        char buf[64];
        snprintf(buf, sizeof(buf), "%.17g", d);
        /* Remove trailing zeros but keep at least one decimal if not integer */
        if (strchr(buf, '.') && !strchr(buf, 'e') && !strchr(buf, 'E')) {
            char *end = buf + strlen(buf) - 1;
            while (*end == '0') *end-- = '\0';
            if (*end == '.') *end = '\0';
        }
        fputs(buf, f);
    }
}

