    int i, sp;
    char pad[256];
    for (i = 0; i < indent; i++) pad[i] = ' ';
    pad[indent] = '\0';

    switch (v->type) {
        case J_NULL: fputs("null", f); break;
        case J_BOOL: fputs(v->bval ? "true" : "false", f); break;
        case J_NUMBER: print_number(v->nval, f); break;
        case J_STRING: print_string_escaped(v->sval, f); break;
        case J_ARRAY:
            if (v->count == 0) { fputs("[]", f); break; }
            fputs("[\n", f);
            for (i = 0; i < v->count; i++) {
                for (sp = 0; sp < (indent + 1) * 2; sp++) fputc(' ', f);
                print_value(v->items[i], indent + 1, f);
                if (i < v->count - 1) fputc(',', f);
                fputc('\n', f);
            }
            fputs(pad, f);
            fputc(']', f);
            break;
        case J_OBJECT:
            if (v->count == 0) { fputs("{}", f); break; }
            /* Sort keys */
            jpair *sorted = (jpair *)malloc(v->count * sizeof(jpair));
            memcpy(sorted, v->pairs, v->count * sizeof(jpair));
